<?php
require_once __DIR__ . '/_layout.php';requirePermission('expenses.manage');
if(requestMethod()==='POST'){requireCsrfPost();$receipt=null;try{if(($_POST['action']??'')!=='create')throw new InvalidArgumentException(t('validation.invalid_action'));$agencyId=(int)($_POST['agency_id']??0);financeAssertAgency($agencyId);if(isset($_FILES['receipt'])&&($_FILES['receipt']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE)$receipt=storeValidatedDocument($_FILES['receipt'],'expense_receipts');$id=createExpense(['agency_id'=>$agencyId,'vehicle_id'=>$_POST['vehicle_id']??null,'contract_id'=>$_POST['contract_id']??null,'category'=>$_POST['category']??'other','supplier'=>$_POST['supplier']??'','description'=>$_POST['description']??'','amount'=>$_POST['amount']??'','method'=>$_POST['method']??'','expense_date'=>$_POST['expense_date']??'','receipt'=>$receipt??[],'idempotency_key'=>$_POST['idempotency_key']??'']);flash('success',t('message.expense_created'));}catch(AuthorizationException$e){if($receipt)removeNewStoredUpload($receipt['path']);http_response_code(403);exit(t('validation.not_authorized'));}catch(InvalidArgumentException|DomainException$e){if($receipt)removeNewStoredUpload($receipt['path']);flash('danger',$e->getMessage());}catch(Throwable$e){if($receipt)removeNewStoredUpload($receipt['path']);reportDatabaseError($e,'Expense operation failed');flash('danger',t('message.expense_failed'));}safeRedirect('expenses.php');}
[$ids,$ph]=financeScopedPlaceholders(currentAgencyIds());$agencies=dbFetchAll("SELECT id,name FROM agencies WHERE id IN ($ph) AND archived_at IS NULL ORDER BY name",$ids);$vehicles=dbFetchAll("SELECT id,registration_number FROM vehicles WHERE agency_id IN ($ph) AND archived_at IS NULL ORDER BY registration_number",$ids);$expenses=dbFetchAll("SELECT e.*,a.name agency_name,v.registration_number FROM expenses e JOIN agencies a ON a.id=e.agency_id LEFT JOIN vehicles v ON v.id=e.vehicle_id WHERE e.agency_id IN ($ph) ORDER BY e.expense_date DESC,e.id DESC LIMIT 200",$ids);backofficeHeader(t('page.expenses.title'),'expenses.php');pageHeader('page.expenses.title','page.expenses.description',['breadcrumbs'=>[['label'=>'nav.finance'],['label'=>'nav.expenses']],'primary'=>['label'=>'action.add_expense','href'=>'#new-expense']]);?>
<div class="grid"><section class="card" id="new-expense"><div class="section-card-header"><h2><?=navigationIcon('finance')?><?=e(t('section.record_expense'))?></h2></div><form method="post" enctype="multipart/form-data"><?=csrfField()?><?=financeIdempotencyField('expense.create')?><input type="hidden" name="action" value="create"><label><?=e(t('field.agency'))?><select name="agency_id"><?php foreach($agencies as$a):?><option value="<?=e($a['id'])?>"><?=e($a['name'])?></option><?php endforeach;?></select></label><label><?=e(t('field.vehicle'))?><select name="vehicle_id"><option value=""><?=e(t('common.unassigned'))?></option><?php foreach($vehicles as$v):?><option value="<?=e($v['id'])?>"><?=isolatedValue($v['registration_number'],'reference-value')?></option><?php endforeach;?></select></label><label><?=e(t('field.category'))?><select name="category"><?php foreach(['maintenance','repair','insurance','technical_inspection','tax','cleaning','fuel','leasing','parking','fine','partner_commission','administration','other']as$c):?><option value="<?=e($c)?>"><?=e(t('option.'.$c))?></option><?php endforeach;?></select></label><label><?=e(t('field.supplier'))?><input name="supplier"></label><label><?=e(t('field.description'))?><input name="description" required maxlength="255"></label><label><?=e(t('field.amount'))?><input name="amount" type="number" step="0.01" inputmode="decimal" required></label><label><?=e(t('field.method'))?><select name="method"><?php foreach(financePaymentMethods()as$m):?><option value="<?=e($m)?>"><?=e(t('option.'.$m))?></option><?php endforeach;?></select></label><label><?=e(t('field.date'))?><input type="date" name="expense_date" value="<?=e(date('Y-m-d'))?>" required></label><label><?=e(t('field.document'))?><input type="file" name="receipt" accept="application/pdf,image/jpeg,image/png,image/webp"></label><button class="btn primary"><?=e(t('action.record_expense'))?></button></form></section>
<section class="card"><div class="section-card-header"><h2><?=navigationIcon('finance')?><?=e(t('section.expense_register'))?></h2></div><div class="table-wrap"><table><thead><tr><th><?=e(t('field.date'))?></th><th><?=e(t('field.agency'))?></th><th><?=e(t('field.description'))?></th><th><?=e(t('field.amount'))?></th><th><?=e(t('field.method'))?></th><th><?=e(t('common.status'))?></th></tr></thead><tbody><?php foreach($expenses as$expense):?><tr><td><?=formattedDate($expense['expense_date'])?></td><td><?=e($expense['agency_name'])?></td><td><a href="expense_detail.php?id=<?=e($expense['id'])?>"><?=e($expense['description'])?></a></td><td><?=money($expense['amount'],$expense['currency'])?></td><td><?=e($expense['method']?t('option.'.$expense['method']):t('common.legacy_unspecified'))?></td><td><?=statusBadge($expense['status'])?></td></tr><?php endforeach;?></tbody></table></div></section></div><?php backofficeFooter();
